import js from "@eslint/js"
import importPlugin from "eslint-plugin-import"
import unicorn from "eslint-plugin-unicorn"
import tseslint from "typescript-eslint"
import { ambientAuthority, invariants, swallowedCause, uninstalledSafety } from "../../../../eslint.invariants.js"
import { jsdocConvention } from "../../../../eslint.jsdoc.js"

export default tseslint.config(
  {
    ignores: ["**/dist", "**/build", "**/coverage"]
  },
  js.configs.recommended,
  importPlugin.flatConfigs.recommended,
  importPlugin.flatConfigs.typescript,
  {
    files: ["src/**/*.ts", "examples/**/*.ts"],
    extends: [tseslint.configs.recommended],
    languageOptions: {
      parserOptions: {
        // The test project covers src and examples; examples are outside the
        // build project, so the project service would not find them.
        project: "./tsconfig.test.json",
        tsconfigRootDir: import.meta.dirname
      }
    },
    settings: {
      "import/resolver": {
        typescript: {
          project: ["./tsconfig.json"]
        }
      }
    },
    plugins: {
      unicorn
    },
    rules: {
      "@typescript-eslint/array-type": ["error", { default: "generic", readonly: "generic" }],
      "@typescript-eslint/consistent-type-imports": ["error", { fixStyle: "inline-type-imports" }],
      "@typescript-eslint/no-explicit-any": "off",
      "@typescript-eslint/no-import-type-side-effects": "error",
      "@typescript-eslint/no-unnecessary-type-assertion": "error",
      "@typescript-eslint/no-unnecessary-type-constraint": "error",
      "@typescript-eslint/no-unused-vars": ["error", { argsIgnorePattern: "^_", varsIgnorePattern: "^_" }],
      "@typescript-eslint/no-useless-empty-export": "error",
      "import/no-duplicates": "error",
      "import/no-empty-named-blocks": "error",
      "import/no-self-import": "error",
      "no-await-in-loop": "off",
      "no-console": "error",
      "no-fallthrough": "off",
      "no-shadow": "off",
      "no-unneeded-ternary": "error",
      "no-unused-vars": "off",
      "no-useless-concat": "error",
      "no-useless-constructor": "error",
      "no-var": "error",
      "object-shorthand": "off",
      "require-yield": "off",
      "unicorn/no-abusive-eslint-disable": "error",
      "unicorn/no-accessor-recursion": "error",
      "unicorn/prefer-array-flat-map": "error"
    }
  },
  {
    files: ["src/FlowProxyServer.ts"],
    rules: {
      "@typescript-eslint/no-unnecessary-type-assertion": "off"
    }
  },
  ...jsdocConvention,
  {
    // Unlike the shared convention, this package forbids the `@slop` review
    // marker: it is bookkeeping, not documentation.
    files: ["src/**/*.ts"],
    rules: {
      "jsdoc/check-tag-names": ["error", { definedTags: ["category", "since"] }]
    }
  },
  ...invariants(uninstalledSafety, swallowedCause, ambientAuthority)
)

{
  "name": "@smthrs/engine",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "engine"
  },
  "description": "The runtime that executes @smthrs/flow flows, plus HTTP and RPC transport projections",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/flows/engine"
  },
  "bugs": {
    "url": "https://github.com/smithersai/smithers/issues"
  },
  "tags": [
    "typescript",
    "effect",
    "flow",
    "durability"
  ],
  "keywords": [
    "typescript",
    "effect",
    "flow",
    "durability"
  ],
  "engines": {
    "node": ">=22.19.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./FlowEngine": "./src/FlowEngine/index.ts",
    "./FlowEngine/*": null,
    "./internal/*": null,
    "./*/index": null,
    "./FlowProxy": "./src/FlowProxy.ts",
    "./Hosts": "./src/Hosts.ts",
    "./PlacedAction": "./src/PlacedAction.ts",
    "./FlowProxyServer": "./src/FlowProxyServer.ts",
    "./index": "./src/index.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "THIRD_PARTY_NOTICES.md",
    "README.md",
    "CHANGELOG.md",
    "VENDOR.md",
    "docs/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./FlowEngine": {
        "import": {
          "types": "./dist/esm/FlowEngine/index.d.ts",
          "default": "./dist/esm/FlowEngine/index.js"
        },
        "require": {
          "types": "./dist/cjs/FlowEngine/index.d.ts",
          "default": "./dist/cjs/FlowEngine/index.js"
        }
      },
      "./FlowEngine/*": null,
      "./internal/*": null,
      "./*/index": null,
      "./FlowProxy": {
        "import": {
          "types": "./dist/esm/FlowProxy.d.ts",
          "default": "./dist/esm/FlowProxy.js"
        },
        "require": {
          "types": "./dist/cjs/FlowProxy.d.ts",
          "default": "./dist/cjs/FlowProxy.js"
        }
      },
      "./Hosts": {
        "import": {
          "types": "./dist/esm/Hosts.d.ts",
          "default": "./dist/esm/Hosts.js"
        },
        "require": {
          "types": "./dist/cjs/Hosts.d.ts",
          "default": "./dist/cjs/Hosts.js"
        }
      },
      "./PlacedAction": {
        "import": {
          "types": "./dist/esm/PlacedAction.d.ts",
          "default": "./dist/esm/PlacedAction.js"
        },
        "require": {
          "types": "./dist/cjs/PlacedAction.d.ts",
          "default": "./dist/cjs/PlacedAction.js"
        }
      },
      "./FlowProxyServer": {
        "import": {
          "types": "./dist/esm/FlowProxyServer.d.ts",
          "default": "./dist/esm/FlowProxyServer.js"
        },
        "require": {
          "types": "./dist/cjs/FlowProxyServer.d.ts",
          "default": "./dist/cjs/FlowProxyServer.js"
        }
      },
      "./index": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      }
    }
  },
  "scripts": {
    "lint": "eslint src examples --max-warnings=0 && dprint check",
    "format": "dprint fmt",
    "build": "node scripts/build.mjs",
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "circular": "node ../../../repo-targets/scripts/circular.mjs",
    "test": "vitest",
    "coverage": "vitest --coverage"
  },
  "dependencies": {
    "@smthrs/canonical": "1.0.0-rc.16",
    "@smthrs/crypto": "1.0.0-rc.16",
    "@smthrs/flow": "1.0.0-rc.16",
    "@smthrs/journal": "1.0.0-rc.16",
    "@smthrs/keys": "1.0.0-rc.16",
    "@smthrs/plan": "1.0.0-rc.16",
    "@smthrs/capability": "1.0.0-rc.16"
  },
  "devDependencies": {
    "@effect/language-service": "0.87.2",
    "@effect/platform-node": "4.0.5",
    "@effect/vitest": "4.0.5",
    "@eslint/js": "9.39.5",
    "@types/node": "26.4.1",
    "@vitest/coverage-v8": "5.0.0",
    "dprint": "0.57.1",
    "effect": "4.0.5",
    "esbuild": "0.28.2",
    "eslint": "9.39.5",
    "eslint-import-resolver-typescript": "4.4.5",
    "eslint-plugin-import": "2.32.0",
    "eslint-plugin-jsdoc": "64.3.4",
    "eslint-plugin-unicorn": "65.0.0",
    "fast-check": "4.9.0",
    "knip": "6.34.0",
    "madge": "8.0.0",
    "typescript": "5.9.3",
    "typescript-eslint": "8.69.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0"
  },
  "peerDependencies": {
    "effect": "4.0.5"
  }
}

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { configDefaults, defineConfig } from "vitest/config"

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("../../../repo-targets/test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("../../../repo-targets/test-utils/test-process-environment.mjs", import.meta.url))
    ],
    include: [...configDefaults.include, "**/*.{test,spec}.vibe"],
    environment: "node",
    // Vitest's 5 s default is a wall-clock budget, but no suite in this repo
    // asserts on elapsed time — each is bounded by an explicit iteration,
    // cycle, or completion count. The real gate runs those counts under v8
    // coverage instrumentation across parallel workers, where cases that
    // finish in well under a second in isolation have been measured 6-12x
    // slower; that machine-load multiplier, not the workload, is what put
    // correct suites over the default wall. Raise the budget instead of
    // trimming the workload, and keep it FINITE so a genuine hang still
    // fails the run rather than hanging the gate forever.
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      // `enabled: true` makes every `vitest` run compute and ENFORCE these
      // thresholds — a red gate fails the run (issue #20).
      enabled: true,
      provider: "v8",
      // Scope the report directory — and the `.tmp` scratch dir the v8
      // provider clears at run start and reads at run end — to this process.
      // The default `./coverage` is shared, so two concurrent `vitest run`
      // invocations destroy each other: one aborts with a removed-coverage-
      // directory error and the other enforces 100% against a partial
      // profile with every test passing (issues #115/#121).
      reportsDirectory: join(tmpdir(), `flows-engine-coverage-${process.pid}`),
      // Every production module, including the public barrel, is measured.
      include: ["src/**"],
      // The suite must earn complete coverage in every category.
      thresholds: {
        branches: 100,
        functions: 100,
        lines: 100,
        statements: 100
      }
    }
  }
})
